body:
One question I have stumbled across on the same topic - should adopting an already-loaded image into a new document should fire a load event?

Chromium and Webkit seem to say no to this - Firefox indicate that it should. Update the image data says "Wait until the element's node document is fully active" which can be interpreted as meaning either the node document at the time that step is reached or when an active document is adopted.


Chromium and Webkit dont fire a load event for below, Firefox does. I think I would expect a load event to be fired.

Test below:
```html
<!doctype html>
<meta charset="utf-8">
<title>Image load after adoption from removed iframe</title>
<pre id="log"></pre>
<script>
function log(message) {
    document.getElementById("log").textContent += `${message}\n`;
}

const iframe = document.createElement("iframe");

iframe.onload = () => {
    const img = iframe.contentDocument.createElement("img");

    img.onload = () => {
        log("image loaded after adoption");
        log(`width=${img.width} height=${img.height} naturalWidth=${img.naturalWidth} naturalHeight=${img.naturalHeight} complete=${img.complete}`);
    };

    img.onerror = () => {
        log("image errored after adoption");
    };

    img.src = "120.png";
    iframe.contentDocument.body.appendChild(img);

    iframe.remove();
    document.body.appendChild(document.adoptNode(img));
};

document.body.appendChild(iframe);
</script>
```

One other test case is:

```html
<!doctype html>
<meta charset="utf-8">
<title>Already-loaded image adoption from iframe</title>
<pre id="log"></pre>
<script>
function log(message) {
    document.getElementById("log").textContent += `${message}\n`;
}

const iframe = document.createElement("iframe");
iframe.src = "blank.html";

iframe.onload = () => {
    const img = iframe.contentDocument.createElement("img");

    img.onload = () => {
        // Image is now completely available in the iframe's document.
        // Reset the handler and adopt into the main document.
        let fired = false;
        img.onload = () => { fired = true; };
        img.onerror = () => { fired = true; };

        iframe.remove();
        document.body.appendChild(document.adoptNode(img));

        setTimeout(() => {
            log(fired
                ? "load fired after adoption of already-loaded image"
                : "load did not fire after adoption of already-loaded image");
        }, 500);
    };

    img.onerror = () => {
        log("image errored during initial load");
    };

    img.src = "120.png";
    iframe.contentDocument.body.appendChild(img);
};

document.body.appendChild(iframe);
</script>
```

I'm confused—the following testcase only reports a single load event across Firefox, Safari, and Chrome:
```html
<script>
let e = document.createElement('img');
e.src = "https://joshmatthews.net/portrait.jpg";
e.onload = () => {
  console.log('onload');
  e.width *= 2;
};
</script>
```
This doesn't appear to match what the specification describes or what this issue describes.
